 .emoji-toggle{
    display:inline-block;
    background-color:$(main.color);
    color:#fff;
    height:26px;
    line-height:26px;
    font-size:14px;
    cursor:pointer;
    padding:0 10px;
    margin:0 0 10px;
    border-radius:2px;
    transition:background .17s ease
}
 .emoji-toggle:hover{
    background-color:$(main.dark.color)
}
 #emoji-box{
    display:none;
    padding:20px 0 0;
    margin:10px 0;
    border-top:1px dashed #ccc
}
 #emoji-box .mj-item{
    display:inline-block;
    text-align:center;
    font-size:12px;
    font-weight:700;
    padding:0 10px;
    margin:0 0 10px
}
 #emoji-box .sora-moji{
    display:block;
    margin:0 0 5px
}
 .post-body h1,.post-body h2,.post-body h3,.post-body h4,.post-body h5,.post-body h6{
    color:$(title.color);
    font-weight:600;
    margin:0 0 15px
}
 .post-body h1,.post-body h2{
    font-size:24px
}
 .post-body h3{
    font-size:21px
}
 .post-body h4{
    font-size:18px
}
 .post-body h5{
    font-size:16px
}
 .post-body h6{
    font-size:13px
}
 blockquote{
    font-style:italic;
    padding:10px;
    margin:0;
    border-left:4px solid $(main.color)
}
 blockquote:before,blockquote:after{
    display:inline-block;
    font-family:FontAwesome;
    font-style:normal;
    font-weight:400;
    color:#aaa;
    line-height:1
}
 blockquote:before{
    content:'\f10d';
    margin:0 10px 0 0
}
 blockquote:after{
    content:'\f10e';
    margin:0 0 0 10px
}
 .widget .post-body ul,.widget .post-body ol{
    line-height:1.5;
    font-weight:400
}
 .widget .post-body li{
    margin:5px 0;
    padding:0;
    line-height:1.5
}
 .post-body ul{
    padding:0 0 0 20px
}
 .post-body ul li:before{
    content:"\f105";
    font-family:FontAwesome;
    font-size:13px;
    font-weight:400;
    margin:0 5px 0 0
}
 .post-body u{
    text-decoration:underline
}
 .post-body a{
    transition:color .17s ease
}
 .post-body strike{
    text-decoration:line-through
}
 .contact-form{
    overflow:hidden
}
 .contact-form .widget-title{
    display:none
}
 .contact-form .contact-form-name{
    width:calc(50% - 5px)
}
 .contact-form .contact-form-email{
    width:calc(50% - 5px);
    float:right
}
 .sidebar .widget{
    position:relative;
    overflow:hidden;
    padding:20px;
    background: #fff;
    webkit-box-shadow: 0px 1px 4px 0px rgb(0 0 0 / 15%);
    -moz-box-shadow: 0px 1px 4px 0px rgba(0, 0, 0, 0.15);
    box-shadow: 0px 1px 4px 0px rgb(0 0 0 / 15%);
    -webkit-border-radius: 4px;
    -moz-border-radius: 4px;
    border-radius: 4px;
    box-sizing:border-box;
    margin:0 0 35px;
}
 .sidebar .widget-title{
    position:relative;
    float:left;
    width:100%;
    margin:0
}
 .sidebar .widget-title > h3{
    position:relative;
    display:block;
    height:34px;
    font-size:17px;
    color:$(widget.title);
    font-weight:600;
    line-height:34px;
    padding:0;
    margin:0;
    border-bottom:2px solid #f2f2f6
}
 .sidebar .widget-content{
    float:left;
    width:100%;
    box-sizing:border-box;
    padding:15px 0;
    margin:0
}
 ul.social-counter{
    margin:0 -5px
}
 .social-counter li{
    float:left;
    width:20%;
    box-sizing:border-box;
    padding:0 5px;
    margin:10px 0 0
}
 .social-counter li:nth-child(1),.social-counter li:nth-child(2),.social-counter li:nth-child(3),.social-counter li:nth-child(4),.social-counter li:nth-child(5){
    margin-top:0
}
 .social-counter li a{
    display:block;
    height:40px;
    font-size:22px;
    color:#fff;
    text-align:center;
    line-height:40px;
    border-radius:2px;
    transition:opacity .17s
}
 .social-counter li a:hover{
    opacity:.8
}
 .list-label li{
    position:relative;
    display:block;
    padding:7px 0;
    border-top:1px dotted #ebebf3
}
 .list-label li:first-child{
    padding-top:0;
    border-top:0
}
 .list-label li:last-child{
    padding-bottom:0;
    border-bottom:0
}
 .list-label li a{
    display:block;
    color:$(title.color);
    font-size:13px;
    font-weight:400;
    text-transform:capitalize;
    transition:color .17s
}
 .list-label li a:before{
    content:"\f054";
    float:left;
    color:$(title.color);
    font-weight:400;
    font-family:FontAwesome;
    font-size:6px;
    margin:6px 3px 0 0;
    transition:color .17s
}
 .list-label li a:hover{
    color:$(main.color)
}
 .list-label .label-count{
    position:relative;
    float:right;
    font-size:11px;
    font-weight:400;
    text-align:center;
    line-height:16px
}
 .cloud-label li{
    position:relative;
    float:left;
    margin:0 5px 5px 0
}
 .cloud-label li a{
    display:block;
    height:26px;
    background-color:#fdfdff;
    color:$(title.color);
    font-size:12px;
    line-height:26px;
    font-weight:400;
    padding:0 10px;
    border:1px solid #f2f2f6;
    border-radius:3px;
    transition:all .17s ease
}
 .cloud-label li a:hover{
    color:#fff;
    background-color:$(main.color);
    border-color:$(main.color)
}
 .cloud-label .label-count{
    display:none
}
 .sidebar .FollowByEmail > .widget-title > h3{
    margin:0
}
 .FollowByEmail .widget-content{
    position:relative;
    overflow:hidden;
    text-align:center;
    font-weight:400;
    box-sizing:border-box;
    padding:20px
}
 .FollowByEmail .widget-content > h3{
    font-size:17px;
    color:$(widget.title);
    font-weight:600;
    margin:0 0 13px
}
 .FollowByEmail .before-text{
    font-size:13px;
    line-height:1.5em;
    margin:0 0 15px;
    display:block;
    padding:0 10px;
    overflow:hidden
}
 .FollowByEmail .follow-by-email-inner{
    position:relative
}
 .FollowByEmail .follow-by-email-inner .follow-by-email-address{
    width:100%;
    height:32px;
    color:$(title.color);
    font-size:11px;
    font-family:inherit;
    padding:0 10px;
    margin:0 0 10px;
    box-sizing:border-box;
    border:1px solid #eee;
    border-radius:3px;
    transition:ease .17s
}
 .FollowByEmail .follow-by-email-inner .follow-by-email-submit{
    width:100%;
    height:32px;
    font-family:inherit;
    font-size:11px;
    color:#fff;
    background-color:$(main.color);
    text-transform:uppercase;
    text-align:center;
    font-weight:600;
    cursor:pointer;
    margin:0;
    border:0;
    border-radius:3px;
    transition:background .17s ease
}
 .FollowByEmail .follow-by-email-inner .follow-by-email-submit:hover{
    background-color:$(main.dark.color)
}
 #ArchiveList ul.flat li{
    color:$(title.color);
    font-size:13px;
    font-weight:400;
    padding:7px 0;
    border-bottom:1px dotted #eaeaea
}
 #ArchiveList ul.flat li:first-child{
    padding-top:0
}
 #ArchiveList ul.flat li:last-child{
    padding-bottom:0;
    border-bottom:0
}
 #ArchiveList .flat li > a{
    display:block;
    color:$(title.color);
    transition:color .17s
}
 #ArchiveList .flat li > a:hover{
    color:$(main.color)
}
 #ArchiveList .flat li > a:before{
    content:"\f054";
    float:left;
    color:$(title.color);
    font-weight:400;
    font-family:FontAwesome;
    font-size:6px;
    margin:6px 3px 0 0;
    display:inline-block;
    transition:color .17s
}
 #ArchiveList .flat li > a > span{
    position:relative;
    float:right;
    width:16px;
    height:16px;
    background-color:$(main.color);
    color:#fff;
    font-size:11px;
    font-weight:400;
    text-align:center;
    line-height:16px
}
 .common-widget .PopularPosts .post{
    overflow:hidden;
    padding:15px 0 0;
    margin:15px 0 0;
    border-top:1px dotted #ebebf3
}
 .common-widget .PopularPosts .post:first-child{
    padding:0;
    margin:0;
    border:0
}
 .common-widget .PopularPosts .post-image-link{
    position:relative;
    width:75px;
    height:60px;
    float:left;
    overflow:hidden;
    display:block;
    vertical-align:middle;
    margin:0 12px 0 0;
    border-radius:3px
}
 .common-widget .PopularPosts .post-info{
    overflow:hidden
}
 .common-widget .PopularPosts .post-title{
    font-size:15px;
    font-weight:400;
    line-height:1.5em;
    margin:0
}
 .common-widget .PopularPosts .post-title a{
    display:block;
    color:$(title.color);
    transition:color .17s
}
 .common-widget .PopularPosts .post:hover .post-title a{
    color:$(main.color)
}
 .common-widget .PopularPosts .post-date:before{
    font-size:10px
}
 .Text{
    font-size:13px
}
 .contact-form-widget{
    float:left;
    width:100%;
    box-sizing:border-box;
    padding:15px
}
 .contact-form-widget form{
    font-weight:400
}
 .contact-form-widget form > p{
    margin:0
}
 .contact-form-widget form > span{
    color:red
}
 .contact-form-name{
    float:left;
    width:100%;
    height:30px;
    font-family:inherit;
    font-size:13px;
    line-height:30px;
    box-sizing:border-box;
    padding:5px 10px;
    margin:0 0 10px;
    border:1px solid #ebebf3;
    border-radius:3px
}
 .contact-form-email{
    float:left;
    width:100%;
    height:30px;
    font-family:inherit;
    font-size:13px;
    line-height:30px;
    box-sizing:border-box;
    padding:5px 10px;
    margin:0 0 10px;
    border:1px solid #ebebf3;
    border-radius:3px
}
 .contact-form-email-message{
    float:left;
    width:100%;
    font-family:inherit;
    font-size:13px;
    box-sizing:border-box;
    padding:5px 10px;
    margin:0 0 10px;
    border:1px solid #ebebf3;
    border-radius:3px
}
 .contact-form-button-submit{
    float:left;
    width:100%;
    height:30px;
    background-color:$(main.color);
    font-family:inherit;
    font-size:13px;
    color:#fff;
    line-height:30px;
    cursor:pointer;
    box-sizing:border-box;
    padding:0 10px;
    margin:0;
    border:0;
    border-radius:3px;
    transition:background .17s ease
}
 .contact-form-button-submit:hover{
    background-color:$(main.dark.color)
}
 .contact-form-error-message-with-border{
    float:left;
    width:100%;
    background-color:#fbe5e5;
    font-size:11px;
