}
 #footer-about-area .Image .image-caption a:hover{
    color:#aaa
}
 .foot-bar-social{
    float:right;
    width:300px;
    margin:0;
position: relative;
    box-sizing: border-box;
}
.foot-bar-social ul > li {
  float: left;
    margin: 0 0 0 10px;
}
.foot-bar-social ul > li > a {
    display: block;
    width: 32px;
    height: 32px;
    background-color: #000;
    font-size: 14px;
    color: #dbdbdb;
    text-align: center;
    line-height: 32px;
    box-sizing: border-box;
    border: 0;
    border-radius: 2px;
}
 #footer-wrapper .copyright-area{
    float:left;
    font-size:13px;
    display:block;
    height:34px;
    color:#fff;
    font-weight:600;
    line-height:34px
}
 #footer-wrapper .copyright-area a{
    color:#fff;
    transition:color .17s
}
 #menu-footer{
    float:right;
    position:relative;
    display:block
}
 #menu-footer .widget > .widget-title{
    display:none
}
 #menu-footer ul li{
    display:inline-block;
    height:34px;
    padding:0;
    margin:0
}
 #menu-footer ul li a{
    font-size:11px;
    font-weight:600;
    display:block;
    color:#fff;
    text-transform:uppercase;
    line-height:34px;
    padding:0 10px;
    margin:0 0 0 5px;
    transition:color .17s ease
}
 #menu-footer ul li:last-child a{
    padding-right:0;
}
 #menu-footer ul li a:hover{
    color:#efefef
}
 .hidden-widgets{
    display:none;
    visibility:hidden
}
 .back-top{
    display:none;
    z-index:1010;
    width:32px;
    height:32px;
    position:fixed;
    bottom:15px;
    right:15px;
    cursor:pointer;
    overflow:hidden;
    font-size:13px;
    color:#fff;
    text-align:center;
    line-height:32px;
    border-radius:3px
}
 .back-top:before{
    content:'';
    position:absolute;
    top:0;
    left:0;
    right:0;
    bottom:0;
    background-color:$(main.color);
    opacity:.5;
    transition:opacity .17s ease
}
 .back-top:after{
    content:'\f077';
    position:relative;
    font-family:FontAwesome;
    font-weight:400;
    opacity:.8;
    transition:opacity .17s ease
}
 .back-top:hover:before,.back-top:hover:after,.nav-active .back-top:after,.nav-active .back-top:before{
    opacity:1
}
 .error404 #main-wrapper{
