/* Mobile 3 Columns Fix - Optimized */
@media (max-width: 768px) {
  #serv-tile {
    display: grid !important;
    grid-template-columns: repeat(3, 1fr);
    gap: 8px; /* Better spacing */
    padding: 10px; /* More padding */
  }

  #serv-tile > .widget {
    width: 100% !important;
    margin: 0 !important;
    padding: 10px !important; /* Increased padding */
    display: flex !important;
    flex-direction: column;
    align-items: center;
    min-height: 100px; /* Minimum height for consistency */
  }

  /* Icon Container Fix */
  .serv-tile-box-avatar {
    width: 50px !important;
    height: 50px !important;
    margin-bottom: 5px; /* Space between icon and text */
  }

  /* Image/Icon Fix */
  .serv-tile-box-avatar img {
    width: 100% !important;
    height: 100% !important;
    object-fit: contain; /* Prevents image stretching */
  }

  /* Title Text Fix */
  .serv-tile-box-title {
    font-size: 14px !important;
    line-height: 1.3;
    text-align: center;
    text-wrap: balance; /* Better text alignment */
    margin: 0 !important;
  }

  /* Hide Job Counts */
  .serv-tile-box-meta {
    display: none !important;
  }
}/* Mobile 3 Columns Fix - Optimized */
@media (max-width: 768px) {
  #serv-tile {
    display: grid !important;
    grid-template-columns: repeat(3, 1fr);
    gap: 8px; /* Better spacing */
    padding: 10px; /* More padding */
  }

  #serv-tile > .widget {
    width: 100% !important;
    margin: 0 !important;
    padding: 10px !important; /* Increased padding */
    display: flex !important;
    flex-direction: column;
    align-items: center;
    min-height: 100px; /* Minimum height for consistency */
  }

  /* Icon Container Fix */
  .serv-tile-box-avatar {
    width: 50px !important;
    height: 50px !important;
    margin-bottom: 5px; /* Space between icon and text */
  }

  /* Image/Icon Fix */
  .serv-tile-box-avatar img {
    width: 100% !important;
    height: 100% !important;
    object-fit: contain; /* Prevents image stretching */
  }

  /* Title Text Fix */
  .serv-tile-box-title {
    font-size: 14px !important;
    line-height: 1.3;
    text-align: center;
    text-wrap: balance; /* Better text alignment */
    margin: 0 !important;
  }

  /* Hide Job Counts */
  .serv-tile-box-meta {
    display: none !important;
  }
/* --- MOBILE NAV FIXES --- */
@media (max-width: 1024px){
  /* show burger, hide desktop menu */
  .mobile-menu-toggle{ display:block; }
  #main-menu{ display:none; }

  /* drawer defaults */
  .mobile-menu-wrap{
    display:block;
    position:fixed;
    top:70px;
    left:0;
    width:100%;
    max-height:calc(100vh - 70px);
    overflow-y:auto;
    background-color:$(submenu.bg);
    box-shadow:0 10px 30px rgba(0,0,0,0.15);
    visibility:hidden;
    opacity:0;
    transform:translateY(-12px);
    pointer-events:none;
  }
  body.nav-active .mobile-menu-wrap{
    visibility:visible;
    opacity:1;
    transform:translateY(0);
    pointer-events:auto;
  }

  /* lock body scroll and show overlay when drawer is open */
  body.nav-active{ overflow:hidden; }
  body.nav-active .overlay{ display:block; }

  /* submenu toggle behavior in the mobile drawer */
  .mobile-menu ul li.has-sub > .m-sub{ display:none; }
  .mobile-menu ul li.has-sub.show > .m-sub{ display:block; }
}

}

